"use client"

/**
 * The dashboard's hero number — clients with documents still outstanding —
 * remixable by Vendo (06-apps §8).
 *
 * Deliberately self-contained (React only, inline styles) so `vendo sync`
 * static capture reproduces it faithfully inside the sandboxed jail, whose
 * module space is React plus captured sub-sources and whose CSS is the
 * captured app-root stylesheet, not the compiled Tailwind bundle. The values
 * mirror the Cadence brand tokens in `src/app/globals.css`.
 */

const INK = "#111111"
const INK_SOFT = "#46443f"
const INK_FAINT = "#908c85"
const LINE = "#ecebe8"
const LEDGER_GREEN = "#1e7f53"
const STATUS_MISSING = "#a16207"
const STATUS_MISSING_BG = "#faf3e3"
const FONT = 'var(--font-inter, system-ui), ui-sans-serif, system-ui, sans-serif'

// Donut slice colors — ink-family, no traffic-light palette
const SLICE_COLORS = ["#111111", "#908c85", "#c8c5be", "#e2e0db"]

export interface MissingDocsHeroProps {
  /** Clients with at least one outstanding (missing/rejected) document. */
  missingCount: number
  /** All active clients. */
  clientCount: number
  badgeLabel?: string
}

function humanizeStatus(raw: string): string {
  const map: Record<string, string> = {
    missing: "Missing",
    missing_docs: "Missing",
    received: "Received",
    upload_received: "Received",
    verified: "Verified",
    review: "Needs review",
    needs_review: "Needs review",
    rejected: "Rejected",
    overdue: "Overdue",
    pending: "Pending",
  }
  const key = (raw || "").toLowerCase().replace(/-/g, "_")
  return map[key] ?? raw.replace(/_/g, " ").replace(/\b\w/g, c => c.toUpperCase())
}

function DonutChart({ slices }: { slices: { label: string; value: number; color: string }[] }) {
  const total = slices.reduce((s, d) => s + d.value, 0)
  if (total === 0) return null

  const R = 44
  const CX = 56
  const CY = 56
  const STROKE = 18

  let cumAngle = -Math.PI / 2
  const paths = slices.map((slice, i) => {
    const frac = slice.value / total
    const angle = frac * 2 * Math.PI
    const x1 = CX + R * Math.cos(cumAngle)
    const y1 = CY + R * Math.sin(cumAngle)
    cumAngle += angle
    const x2 = CX + R * Math.cos(cumAngle)
    const y2 = CY + R * Math.sin(cumAngle)
    const large = angle > Math.PI ? 1 : 0
    const d = `M ${x1} ${y1} A ${R} ${R} 0 ${large} 1 ${x2} ${y2}`
    return { d, color: slice.color, key: i }
  })

  return (
    <svg width={112} height={112} viewBox="0 0 112 112" aria-hidden>
      {paths.map(p => (
        <path
          key={p.key}
          d={p.d}
          fill="none"
          stroke={p.color}
          strokeWidth={STROKE}
          strokeLinecap="butt"
        />
      ))}
      <circle cx={CX} cy={CY} r={R - STROKE / 2 - 1} fill="#ffffff" />
      <text
        x={CX}
        y={CY - 6}
        textAnchor="middle"
        dominantBaseline="middle"
        fontSize={13}
        fontWeight={600}
        fill={INK}
        fontFamily={FONT}
      >
        {total}
      </text>
      <text
        x={CX}
        y={CY + 10}
        textAnchor="middle"
        dominantBaseline="middle"
        fontSize={9}
        fill={INK_FAINT}
        fontFamily={FONT}
      >
        docs
      </text>
    </svg>
  )
}

function StatusDonut() {
  const [slices, setSlices] = useState<{ label: string; value: number; color: string }[]>([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    let cancelled = false
    async function load() {
      try {
        const result = await tools.list_client_documents({})
        if (cancelled) return
        const docs = Array.isArray(result) ? result : Array.isArray(result?.data) ? result.data : []
        const counts: Record<string, number> = {}
        for (const doc of docs) {
          const s = (doc.status || doc.document_status || "unknown").toLowerCase()
          counts[s] = (counts[s] || 0) + 1
        }
        const entries = Object.entries(counts).sort((a, b) => b[1] - a[1])
        const built = entries.map(([status, value], i) => ({
          label: humanizeStatus(status),
          value,
          color: SLICE_COLORS[i % SLICE_COLORS.length],
        }))
        setSlices(built)
      } catch {
        // leave empty
      } finally {
        if (!cancelled) setLoading(false)
      }
    }
    load()
    return () => { cancelled = true }
  }, [])

  if (loading) {
    return (
      <div style={{ width: 112, height: 112, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <span style={{ fontSize: 11, color: INK_FAINT, fontFamily: FONT }}>Loading…</span>
      </div>
    )
  }

  if (slices.length === 0) {
    return (
      <div style={{ width: 112, height: 112, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <span style={{ fontSize: 11, color: INK_FAINT, fontFamily: FONT }}>No data</span>
      </div>
    )
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 8 }}>
      <DonutChart slices={slices} />
      <div style={{ display: "flex", flexDirection: "column", gap: 3 }}>
        {slices.map((s, i) => (
          <div key={i} style={{ display: "flex", alignItems: "center", gap: 5 }}>
            <span style={{ width: 8, height: 8, borderRadius: 2, background: s.color, flexShrink: 0 }} />
            <span style={{ fontSize: 11, color: INK_SOFT, fontFamily: FONT, whiteSpace: "nowrap" }}>
              {s.label}
              <span style={{ color: INK_FAINT, marginLeft: 4 }}>{s.value}</span>
            </span>
          </div>
        ))}
      </div>
    </div>
  )
}

export function MissingDocsHero({
  missingCount,
  clientCount,
  badgeLabel = "Action needed",
}: MissingDocsHeroProps) {
  return (
    <article
      style={{
        borderRadius: 12,
        border: `1px solid ${LINE}`,
        background: "#ffffff",
        boxShadow: `inset 3px 0 0 ${LEDGER_GREEN}, 0 1px 2px rgba(17,17,17,0.04)`,
        padding: 20,
        fontFamily: FONT,
      }}
    >
      <p
        style={{
          margin: 0,
          fontSize: 13,
          fontWeight: 500,
          whiteSpace: "nowrap",
          color: INK_SOFT,
        }}
      >
        Clients still owing documents
      </p>
      <div
        style={{
          marginTop: 12,
          display: "flex",
          alignItems: "flex-start",
          justifyContent: "space-between",
          gap: 24,
        }}
      >
        {/* Left: hero number + badge + caption */}
        <div style={{ flex: "1 1 auto" }}>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              gap: 12,
            }}
          >
            <span
              style={{
                fontSize: 40,
                lineHeight: 1,
                fontWeight: 600,
                letterSpacing: "-0.025em",
                color: INK,
                fontVariantNumeric: "tabular-nums",
              }}
            >
              {missingCount}
            </span>
            <span
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 6,
                borderRadius: 9999,
                padding: "2px 8px",
                fontSize: 11,
                fontWeight: 500,
                whiteSpace: "nowrap",
                background: STATUS_MISSING_BG,
                color: STATUS_MISSING,
              }}
            >
              <span
                aria-hidden
                style={{
                  width: 6,
                  height: 6,
                  borderRadius: 9999,
                  background: "currentcolor",
                }}
              />
              {badgeLabel}
            </span>
          </div>
          <p
            style={{
              margin: "10px 0 0",
              fontSize: 12,
              color: INK_FAINT,
            }}
          >
            of {clientCount} active clients need chasing
          </p>
        </div>

        {/* Right: donut by document status */}
        <div
          style={{
            flexShrink: 0,
            borderLeft: `1px solid ${LINE}`,
            paddingLeft: 20,
          }}
        >
          <p style={{ margin: "0 0 8px", fontSize: 11, fontWeight: 500, color: INK_SOFT }}>
            Documents by status
          </p>
          <StatusDonut />
        </div>
      </div>
    </article>
  )
}

// <Remixable> derives its remix slot from this identity at runtime, and the
// production bundle minifies the function name away — displayName is the
// React-canonical identity that survives, matching the exported identifier
// sync captures the baseline under.
MissingDocsHero.displayName = "MissingDocsHero"

// The jail's module loader renders a fork's DEFAULT export (08-ui §5), so a
// remixable component must carry one; the named export stays for host imports.
export default MissingDocsHero
